[TFMParameter(NoYes::Yes,"@PRO2183")]
public TFMPromptForUnit parmuseFEFOParameter(TFMPromptForUnit _useFEFOParameter = useFEFOParameter)
{
    useFEFOParameter = _useFEFOParameter;
    return useFEFOParameter;
}

public Map AddFields(Common _common)
{
    Map ret = next AddFields(_common);
    InventTable inventTable = InventTable::find(ret.lookup(extendedTypeStr(ItemId)));
    Qty lineQty = _common.TableId == tableNum(PurchLine) ? _common.(fieldNum(PurchLine,PurchQty)) : (_common.TableId == tableNum(ITMLine) ? _common.(fieldNum(ITMLine,ShipQty)) : 1);
    if (registerExpirationDate && useFEFOParameter)
    {
        boolean localRegisterExpirationDate = lineQty > 0 && InventNumGroup::find(inventTable.BatchNumGroupId).MobInclExpectedDate;
        ret.insert(TFMConstants::RegisterExpirationDate(),  strFmt('%1',localRegisterExpirationDate)); //RegisterExpirationDate
    }

    return ret;
}
